  <body>
    <main id="app"></main>
    <script type="module">
      const app = document.querySelector('#app');

      async function request(path, options) {
        const response = await fetch(path, options);
        const body = await response.json();
        if (!response.ok) throw new Error(body.error || 'Unable to complete request');
        return body;
      }

      function showError(message) {
        document.querySelector('#error').textContent = message;
      }

      let projects = [];

      function appendProject(project) {
        const row = document.createElement('div');
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const open = document.createElement('button');
        open.textContent = 'Open project';
        open.addEventListener('click', () => {
          location.href = `/projects/${project.id}`;
        });
        const summary = document.createElement('div');
        summary.dataset.testid = 'project-summary';
        summary.className = 'project-summary';
        summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
        const details = document.createElement('div');
        details.className = 'project-details';
        details.append(name, summary);
        const archive = document.createElement('button');
        archive.textContent = project.archived ? 'Restore project' : 'Archive project';
        archive.addEventListener('click', async () => {
          archive.disabled = true;
          showError('');
          try {
            const saved = await request(`/api/projects/${project.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ archived: !project.archived }),
            });
            projects = projects.map((item) => item.id === saved.id ? saved : item);
            renderProjects();
          } catch (error) {
            showError(error.message);
            archive.disabled = false;
          }
        });
        const actions = document.createElement('div');
        actions.className = 'row-actions';
        actions.append(open, archive);
        row.append(details, actions);
        document.querySelector('#projects').append(row);
      }

      function renderProjects() {
        const archived = document.querySelector('#project-filter').value === 'Archived';
        document.querySelector('#projects').replaceChildren();
        projects.filter((project) => project.archived === archived).forEach(appendProject);
      }

      async function showProjects() {
        app.innerHTML = `
          <h1>Workboard</h1>
          <form>
            <label for="project-name">Project name</label>
            <div class="fields">
              <input id="project-name" name="name" type="text" autocomplete="off">
              <button type="submit" disabled>Create project</button>
            </div>
          </form>
          <div id="error" role="alert"></div>
          <div class="project-filter">
            <label for="project-filter">Project filter</label>
            <select id="project-filter"><option>Active</option><option>Archived</option></select>
          </div>
          <div id="projects"></div>`;
        app.querySelector('#project-filter').addEventListener('change', renderProjects);
        const form = app.querySelector('form');
        const input = app.querySelector('input');
        const submit = form.querySelector('button');
        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          const name = input.value.trim();
          if (!name) return showError('Project name is required');
          showError('');
          submit.disabled = true;
          try {
            const project = await request('/api/projects', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ name }),
            });
            projects.push(project);
            renderProjects();
            input.value = '';
            input.focus();
          } catch (error) {
            showError(error.message);
          } finally {
            submit.disabled = false;
          }
        });
        try {
          projects = await request('/api/projects');
          renderProjects();
        } catch (error) {
          showError(error.message);
        } finally {
          submit.disabled = false;
        }
      }

      async function showProject(id) {
        app.innerHTML = '<button id="back">Projects</button><h1>Loading project…</h1><div id="error" role="alert"></div>';
        app.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
        try {
          const project = await request(`/api/projects/${id}`);
          app.querySelector('h1').textContent = project.name;
          document.title = `${project.name} — Workboard`;
          if (project.archived) {
            const notice = document.createElement('p');
            notice.textContent = 'Archived project';
            app.querySelector('h1').after(notice);
          }
          const controls = document.createElement('section');
          controls.innerHTML = `
            <form>
              <label for="task-title">Task title</label>
              <div class="fields">
                <input id="task-title" name="title" type="text" autocomplete="off">
                <button type="submit" disabled>Create task</button>
              </div>
            </form>
            <div class="task-filter">
              <label for="task-filter">Task filter</label>
              <select id="task-filter">
                <option>All</option><option>Open</option><option>Completed</option>
              </select>
            </div>
            <div id="tasks"></div>`;
          app.append(controls);
          const form = controls.querySelector('form');
          const input = controls.querySelector('#task-title');
          const submit = form.querySelector('button');
          const filter = controls.querySelector('select');
          const list = controls.querySelector('#tasks');
          let tasks = [];

          function renderTasks() {
            list.replaceChildren();
            for (const task of tasks) {
              if (filter.value === 'Open' && task.completed) continue;
              if (filter.value === 'Completed' && !task.completed) continue;
              const row = document.createElement('div');
              row.dataset.testid = 'task-row';
              const title = document.createElement('span');
              title.textContent = task.title;
              const checkbox = document.createElement('input');
              checkbox.type = 'checkbox';
              checkbox.checked = task.completed;
              checkbox.disabled = project.archived;
              checkbox.setAttribute('aria-label', `Complete ${task.title}`);
              checkbox.addEventListener('change', async () => {
                checkbox.disabled = true;
                showError('');
                try {
                  const saved = await request(`/api/projects/${id}/tasks/${task.id}`, {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ completed: checkbox.checked }),
                  });
                  task.completed = saved.completed;
                  renderTasks();
                } catch (error) {
                  checkbox.checked = task.completed;
                  showError(error.message);
                } finally {
                  checkbox.disabled = project.archived;
                }
              });
              row.append(checkbox, title);
              list.append(row);
            }
          }

          filter.addEventListener('change', renderTasks);
          form.addEventListener('submit', async (event) => {
            event.preventDefault();
            if (project.archived) return;
            const title = input.value.trim();
            if (!title) return showError('Task title is required');
            showError('');
            submit.disabled = true;
            try {
              const task = await request(`/api/projects/${id}/tasks`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ title }),
              });
              tasks.push(task);
              renderTasks();
              input.value = '';
              input.focus();
            } catch (error) {
              showError(error.message);
            } finally {
              submit.disabled = project.archived;
            }
          });
          tasks = await request(`/api/projects/${id}/tasks`);
          renderTasks();
          submit.disabled = project.archived;
        } catch (error) {
          app.querySelector('h1').textContent = 'Project unavailable';
          showError(error.message);
        }
      }

      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) showProject(match[1]);
      else showProjects();
    </script>
  </body>
</html>

